(function(){
  "use strict";
  const S=window.OneLineStore,B=window.OneLineBackend,root=document.getElementById('admin-app');
  const requested=(document.body.dataset.portalRole||'admin').toLowerCase();
  const esc=S.esc,money=S.money;
  const state={profile:null,view:requested==='receiver'?'orders':requested==='staff'?'stock':'products',loading:true,error:'',toast:'',menu:false,products:[],categories:[],subcategories:[],subitems:[],orders:[],orderItems:[],activity:[],customers:[],carts:[],profiles:[],customCatalogCategories:[],customCatalogItems:[],enquiries:[],customSchemaReady:true,editor:null,b2bEditor:null,editSections:{},subEditor:null,categoryEditor:null,categoryType:'ready',customCategoryEditor:null,customItemEditor:null,query:'',orderQuery:'',orderFilter:'All',customerQuery:'',enquiryQuery:'',productCategoryFilter:'',b2bCategoryFilter:''};
  const sb=()=>B?.supa?.();
  const img=(src,alt='')=>'<img src="'+esc(src||'assets/product-placeholder.svg')+'" alt="'+esc(alt)+'" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src=\'assets/product-placeholder.svg\'">';
  const adminLoader=(label='Loading')=>'<div class="admin-loading">'+esc(label)+'…</div>';
  const roles=['admin','management','staff','receiver'];
  const labels={admin:'Admin',management:'Management',staff:'Staff',receiver:'Order Receiving'};
  function notify(msg){state.toast=msg;render();clearTimeout(notify.t);notify.t=setTimeout(()=>{state.toast='';renderToast();},2400);}
  function render(){
    if(!B?.configured?.()){root.innerHTML=setupScreen();return;}
    if(state.loading&&!state.profile){root.innerHTML=adminLoader('Loading portal');return;}
    if(!state.profile){root.innerHTML=loginScreen();bind();return;}
    if(!roleOkay()){root.innerHTML=wrongPortal();bind();return;}
    if(state.loading){root.innerHTML=adminLoader('Loading live data');return;}
    root.innerHTML=shell();bind();renderToast();
  }
  function allowed(v){
    const r=requested;
    if(r==='receiver')return ['orders','settings'].includes(v);
    if(r==='staff')return ['stock','settings'].includes(v);
    if(r==='management')return ['products','categories','customCatalog','b2b','subitems','settings'].includes(v);
    return ['products','categories','customCatalog','b2b','enquiries','subitems','accounts','settings'].includes(v);
  }
  function canEditCatalog(){return requested==='admin'||requested==='management';}
  function canDeleteProduct(){return requested==='admin';}
  function canOrderStatus(){return requested==='admin'||requested==='receiver';}
  function canManageStructure(){return requested==='admin'||requested==='management';}
  function canDeleteStructure(){return requested==='admin';}
  function nav(v,label){return allowed(v)?'<button data-view="'+v+'" class="'+(state.view===v?'active':'')+'">'+label+'</button>':'';}
  function roleOkay(){return state.profile&&(state.profile.role===requested||state.profile.role==='admin');}
  function setupScreen(){return '<main class="portal-gate"><section class="portal-gate-card setup"><img src="one-line-logo.webp" alt="One-Line"><span class="portal-kicker">PRODUCTION SETUP</span><h1>Connect the client Supabase project</h1><p>This build intentionally contains no demo catalogue or secret credentials.</p><div class="setup-list"><b>1. Run <code>supabase/schema.sql</code> in the client Supabase SQL editor.</b><b>2. Supabase URL, publishable key and MSG91 Widget client values are already configured in <code>js/config.js</code>.</b><b>3. Deploy the Edge Functions in <code>supabase/functions</code>.</b><b>4. Add the account-level MSG91_AUTH_KEY as an Edge Function secret.</b><b>5. Create the first admin Auth user and matching profile row using <code>supabase/SETUP.md</code>.</b></div><a class="primary-btn" href="index.html">Open customer site</a></section></main>';}
  function loginScreen(){return '<main class="portal-gate"><section class="portal-gate-card"><img src="one-line-logo.webp" alt="One-Line"><span class="portal-kicker">'+esc(labels[requested]||'Portal').toUpperCase()+'</span><h1>Portal login</h1><p>Use the username and password created by an administrator.</p><form id="portalLogin"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label>'+(state.error?'<p class="portal-error">'+esc(state.error)+'</p>':'')+'<button class="primary-btn" type="submit">Sign in</button></form><a class="portal-back" href="index.html">← Back to store</a></section></main>';}
  function wrongPortal(){return '<main class="portal-gate"><section class="portal-gate-card"><span class="portal-kicker">ACCOUNT ROLE</span><h1>This is a '+esc(labels[state.profile.role]||state.profile.role)+' account</h1><p>Open the matching portal, or sign out and use another account.</p><div class="portal-role-links"><a href="admin.html">Admin</a><a href="management.html">Management</a><a href="staff.html">Staff</a><a href="receiver.html">Order receiving</a></div><button class="secondary-btn" data-action="logout">Sign out</button></section></main>';}
  function shell(){
    if(!allowed(state.view))state.view=requested==='receiver'?'orders':requested==='staff'?'stock':'products';
    const profileIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
    const roleNav=requested==='admin'
      ?nav('products','Ready Made')+nav('customCatalog','Custom Catalogue')+nav('b2b','B2B')+nav('categories','Categories')+nav('enquiries','Enquiries')+nav('subitems','Subitems')+nav('accounts','Accounts')+nav('settings','Settings')
      :requested==='management'
        ?nav('products','Ready Made')+nav('customCatalog','Custom Catalogue')+nav('b2b','B2B')+nav('categories','Categories')+nav('subitems','Subitems')+nav('settings','Settings')
        :requested==='staff'
          ?nav('stock','Stock / Sold')+nav('settings','Settings')
          :nav('orders','Orders')+nav('settings','Settings');
    const readyCount=state.products.filter(p=>p.audience!=='b2b').length,b2bCount=state.products.filter(p=>p.audience==='b2b').length;
    const summary=requested==='admin'
      ?readyCount+' Ready Made · '+state.customCatalogItems.length+' Custom · '+b2bCount+' B2B'
      :requested==='management'
        ?readyCount+' Ready Made · '+state.customCatalogItems.length+' Custom · '+b2bCount+' B2B'
        :requested==='staff'?'Search exact item/variant and mark quantity sold':'Order receiving';
    return '<div class="admin-shell portal-'+requested+'"><header class="admin-head"><a class="admin-logo" href="index.html">'+img('one-line-logo.webp','One-Line')+'<span><b>ONE-LINE</b><small>'+esc(labels[requested])+'</small></span></a><button class="menu-toggle" data-action="menu" aria-label="Open menu">☰</button><nav class="admin-menu '+(state.menu?'open':'')+'">'+roleNav+'</nav><button class="portal-profile-button" data-view="settings" aria-label="Open portal settings">'+profileIcon+'</button></header><div class="status-card simple-status-card"><span>'+esc(summary)+'</span></div><main class="admin-main">'+view()+'</main><div class="portal-credit">Developed by <a href="https://quartzsolution.netlify.app/" target="_blank" rel="noopener noreferrer">Quartz Web Solutions</a></div><div class="toast" id="adminToast"></div></div>';
  }
  function view(){return({dashboard:dashboardView,products:productsView,categories:categoriesView,customCatalog:customCatalogView,b2b:b2bView,enquiries:enquiriesView,subitems:subitemsView,stock:stockView,orders:ordersView,customers:customersView,carts:cartsView,activity:activityView,accounts:accountsView,settings:settingsView})[state.view]?.()||((requested==='admin'||requested==='management')?productsView():requested==='staff'?stockView():ordersView());}
  function dashboardView(){
    const today=new Date().toDateString(),todayOrders=state.orders.filter(o=>new Date(o.created_at).toDateString()===today),low=stockRows().filter(x=>x.stock<=5),activeCarts=state.carts.filter(c=>Number(c.piece_count||0)>0),recentCustomers=state.customers.filter(c=>Date.now()-new Date(c.last_seen_at||c.created_at).getTime()<86400000).length;
    return '<section class="portal-overview"><div class="panel-head"><div><p class="tag">LIVE OVERVIEW</p><h1>'+esc(labels[requested])+'</h1><p>Catalogue, customers, live carts, stock and orders in one place.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh</button></div><div class="metric-grid admin-metric-grid"><article><span>Ready Made</span><b>'+state.products.length+'</b><small>Stock catalogue items</small></article><article><span>Orders today</span><b>'+todayOrders.length+'</b><small>'+money(todayOrders.reduce((n,o)=>n+Number(o.total||0),0))+'</small></article><article><span>Customers</span><b>'+state.customers.length+'</b><small>'+recentCustomers+' active in 24h</small></article><article><span>Live carts</span><b>'+activeCarts.length+'</b><small>'+activeCarts.reduce((n,c)=>n+Number(c.piece_count||0),0)+' pieces selected</small></article><article><span>Low stock</span><b>'+low.length+'</b><small>Options with 5 or fewer</small></article><article><span>Enquiries</span><b>'+state.enquiries.length+'</b><small>Customization catalogue requests</small></article></div><div class="admin-quick-actions">'+(canEditCatalog()?'<button data-action="new-product">+ Ready Made</button><button data-action="new-custom-item" '+(!state.customCatalogCategories.length?'disabled':'')+'>+ Customize item</button>':'')+'<button data-view="orders">Track orders</button>'+(requested==='admin'?'<button data-view="enquiries">View enquiries</button><button data-view="customCatalog">Custom catalogue</button>':'')+''+((requested==='admin'||requested==='management')?'<button data-view="carts">View live carts</button><button data-view="customers">Customers</button>':'')+'</div>'+(low.length?'<div class="clean-card"><div class="panel-head"><div><p class="tag">ATTENTION</p><h2>Low stock</h2></div><button data-view="stock">Open stock desk</button></div><div class="compact-table">'+low.slice(0,8).map(r=>'<div><b>'+esc(r.name)+'</b><span>'+esc(r.option)+'</span><strong>'+r.stock+'</strong></div>').join('')+'</div></div>':'')+'</section>';
  }
  function productSearchList(){
    const q=state.query.trim().toLowerCase(),cat=state.productCategoryFilter;
    return state.products.filter(p=>{
      if(p.audience==='b2b')return false;
      if(cat&&p.categoryId!==cat)return false;
      if(!q)return true;
      const variants=(p.variants||[]).map(v=>[v.color,v.size,v.barcode].join(' ')).join(' ');
      const subs=(p.subItems||[]).map(si=>[si.name,si.code,si.barcode,(si.variants||[]).map(v=>[v.color,v.size,v.barcode].join(' ')).join(' ')].join(' ')).join(' ');
      return [p.name,p.code,p.barcode,p.category,p.subcategory,variants,subs].join(' ').toLowerCase().includes(q);
    });
  }
  function productsView(){
    if(state.editor)return productEditorView();const list=productSearchList();
    return '<section class="clean-card simple-workspace"><div class="panel-head"><div><p class="tag">READY MADE</p><h1>Ready Made products</h1><p>Stock products with variants and subitems. B2B and Custom Catalogue are managed separately.</p></div>'+(canEditCatalog()?'<button class="submit-small" data-action="new-product">+ Add Ready Made</button>':'')+'</div><div class="list-controls ready-list-controls"><select id="productCategoryFilter"><option value="">All categories</option>'+state.categories.map(c=>'<option value="'+c.id+'" '+(state.productCategoryFilter===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select><input id="productSearch" type="search" value="'+esc(state.query)+'" placeholder="Search name, item code, barcode, colour, size or subitem"><span>'+list.length+' item'+(list.length===1?'':'s')+'</span></div><div class="admin-product-list">'+(list.length?list.map(p=>'<article class="admin-product"><div class="admin-list-image image-loading-shell">'+img(p.image||p.images?.[0],p.name)+'</div><div class="admin-product-copy"><span class="audience-pill">READY MADE</span><b>'+esc(p.name||'Unnamed item')+'</b><small>'+esc(p.category||'')+(p.subcategory?' · '+esc(p.subcategory):'')+' · '+(p.variants?.length||0)+' option'+((p.variants?.length||0)===1?'':'s')+'</small></div><div class="admin-product-meta"><b>'+esc(p.code||'------')+'</b><small>'+esc(p.barcode||'No barcode')+'</small></div><div class="admin-product-price"><b>'+money(p.price||0)+'</b><small>'+Number(p.stock||0)+' stock</small></div><div class="row-actions">'+(canEditCatalog()?'<button data-action="edit-product" data-id="'+esc(p.id)+'">Edit</button>'+(canDeleteProduct()?'<button class="danger-link" data-action="delete-product" data-id="'+esc(p.id)+'">Delete</button>':''):'')+'</div></article>').join(''):'<div class="empty-admin">No Ready Made products yet.</div>')+'</div></section>';
  }
  function blankProduct(){return{id:'',name:'',description:'',code:'',barcode:'',categoryId:state.categories[0]?.id||'',subcategoryId:'',audience:'retail',price:0,mrp:0,type:'Colour + Option',optionTitle:'Size',stock:0,images:[],variants:[{color:'',size:'',stock:0,price:0,barcode:'',image:'',active:true}],subItemIds:[],active:true};}
  function beginProduct(p){state.editor=p?{...structured(p),subItemIds:(p.subItems||[]).map(x=>x.id)}:blankProduct();state.editSections={basic:!p,media:!p,pricing:!p,variants:!p,subitems:!p};state.view='products';render();}
  function structured(v){return typeof structuredClone==='function'?structuredClone(v):JSON.parse(JSON.stringify(v));}
  function sectionBox(key,title,desc,body){const editable=!!state.editSections[key],existing=!!state.editor.id;return '<section class="portal-edit-section '+(editable?'editing':'')+'"><header><div><b>'+title+'</b><small>'+desc+'</small></div>'+(existing?'<button type="button" data-edit-section="'+key+'">'+(editable?'Done':'Edit')+'</button>':'')+'</header><fieldset '+(editable?'':'disabled')+'>'+body+'</fieldset></section>';}
  function variantRowsHtml(p,variants){
    if(p.type==='Simple')return '<div class="variant-empty-note"><b>Simple product</b><span>Stock uses the Simple stock field above. Change Product type to add exact options.</span></div>';
    return '<div class="variant-quick-builder"><div class="variant-quick-copy"><b>Quick add options</b><small>Wellone-style builder: add many exact options at once, then fine-tune rate, quantity, visibility and image below.</small></div><div class="variant-quick-grid">'+(p.type==='Colour + Option'?'<label>Colour<input id="variantQuickColor" placeholder="Black / Blue"></label>':'')+'<label>'+esc(p.optionTitle||'Option')+' values<input id="variantQuickValues" placeholder="S, M, L, XL"></label><label>Qty each<input id="variantQuickQty" type="number" min="0" value="0"></label><label>Rate each<input id="variantQuickPrice" type="number" min="0" step="0.01" value="'+Number(p.price||0)+'"></label><button type="button" data-action="quick-add-variants">Add options</button></div></div><div class="variant-admin-list enhanced">'+(variants.length?variants.map((v,i)=>'<article class="enhanced-variant-row"><div class="enhanced-variant-title"><b>'+esc([v.color,v.size].filter(Boolean).join(' · ')||('Option '+(i+1)))+'</b><button type="button" data-remove-variant="'+i+'">Remove</button></div><div class="enhanced-variant-fields">'+(p.type==='Colour + Option'?'<label>Colour<input data-v="color" data-i="'+i+'" value="'+esc(v.color||'')+'" placeholder="Black"></label>':'<input type="hidden" data-v="color" data-i="'+i+'" value="">')+'<label>'+esc(p.optionTitle||'Option')+'<input data-v="size" data-i="'+i+'" value="'+esc(v.size||'')+'" placeholder="M / 500ml"></label><label>Quantity<input data-v="stock" data-i="'+i+'" type="number" min="0" value="'+Number(v.stock||0)+'"></label><label>Final rate<input data-v="price" data-i="'+i+'" type="number" min="0" step="0.01" value="'+Number(v.price??p.price??0)+'"></label><label>Barcode<input data-v="barcode" data-i="'+i+'" value="'+esc(v.barcode||'')+'" placeholder="Optional"></label></div><div class="variant-image-visibility"><label class="variant-active-toggle"><input type="checkbox" data-v-active="'+i+'" '+(v.active!==false?'checked':'')+'><span><b>Available</b><small>Turn off to hide this exact option.</small></span></label><div class="variant-image-picker">'+(v.image?img(v.image,[v.color,v.size].filter(Boolean).join(' ')):'<div class="variant-image-placeholder">No separate image</div>')+'<label><span>'+(v.image?'Replace image':'Add option image')+'</span><input type="file" accept="image/*" data-variant-image-upload="'+i+'"></label>'+(v.image?'<button type="button" data-clear-variant-image="'+i+'">Use main image</button>':'')+'</div></div></article>').join(''):'<div class="variant-empty-note"><b>No exact options yet</b><span>Use Quick add or Add one option.</span></div>')+'</div><button class="add-single-variant" type="button" data-action="add-variant">+ Add one option</button>';
  }
  function productEditorView(){
    const p=state.editor,subs=state.subcategories.filter(s=>!p.categoryId||s.category_id===p.categoryId),variants=p.variants||[],selected=new Set(p.subItemIds||[]);
    const basic='<div class="editor-grid"><label>Product name<input data-p="name" value="'+esc(p.name||'')+'" required></label><label>Item code<input data-p="code" value="'+esc(p.code||'')+'" maxlength="40" placeholder="Blank = random 6-character code"></label><label>Barcode<input data-p="barcode" value="'+esc(p.barcode||'')+'" placeholder="If entered, barcode becomes item code"></label><label>Category<select data-p="categoryId"><option value="">Select category</option>'+state.categories.map(c=>'<option value="'+c.id+'" '+(p.categoryId===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label>Subcategory<select data-p="subcategoryId"><option value="">No subcategory</option>'+subs.map(s=>'<option value="'+s.id+'" '+(p.subcategoryId===s.id?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select></label><label class="span2">Description<textarea data-p="description" rows="4">'+esc(p.description||'')+'</textarea></label></div>';
    const media='<div class="upload-zone"><input id="productImages" type="file" accept="image/*" multiple><div><b>Upload product images</b><small>Multiple images supported. Exact options can also have their own image.</small></div></div><div class="image-preview-grid">'+(p.images||[]).map((src,i)=>'<div class="image-chip">'+img(src,p.name)+'<button type="button" data-remove-product-image="'+i+'">×</button></div>').join('')+'</div>';
    const pricing='<div class="editor-grid"><label>Base price<input data-p="price" type="number" min="0" step="0.01" value="'+Number(p.price||0)+'"></label><label>MRP<input data-p="mrp" type="number" min="0" step="0.01" value="'+Number(p.mrp||0)+'"></label><label>Simple stock<input data-p="stock" type="number" min="0" value="'+Number(p.stock||0)+'"><small>Used only for Simple product.</small></label><label>Product type<select data-p="type"><option '+(p.type==='Simple'?'selected':'')+'>Simple</option><option '+(p.type==='One Option'?'selected':'')+'>One Option</option><option '+(p.type==='Colour + Option'?'selected':'')+'>Colour + Option</option></select></label><label>Option title<input data-p="optionTitle" value="'+esc(p.optionTitle||'Size')+'" placeholder="Size / ml / Pack"></label></div>';
    const variant=variantRowsHtml(p,variants);
    const subitems='<div class="subitem-link-head"><span>Select reusable matching items for this ready-made product.</span>'+(canManageStructure()?'<button type="button" data-action="open-subitems">Create / manage subitems</button>':'')+'</div><div class="subitem-check-grid">'+(state.subitems.length?state.subitems.map(si=>'<label><input type="checkbox" data-sub-link="'+si.id+'" '+(selected.has(si.id)?'checked':'')+'><span><b>'+esc(si.name)+'</b><small>'+esc(si.code||'')+' · '+(si.variants||[]).length+' options</small></span></label>').join(''):'<p>No reusable subitems are available yet.</p>')+'</div>';
    return '<section class="clean-card editor-page"><div class="panel-head"><div><p class="tag">'+(p.id?'EDIT READY MADE':'NEW READY MADE')+'</p><h1>'+esc(p.name||'Add ready-made product')+'</h1><p>Add or edit only Ready Made product details here.</p></div><button class="ghost-btn" data-action="cancel-product">Back</button></div><form id="productEditor">'+sectionBox('basic','Basic details','Name, searchable code, barcode and normal store category.',basic)+sectionBox('media','Product images','Main catalogue images inherited by options unless an option image is added.',media)+sectionBox('pricing','Pricing & product type','Choose Simple, One Option or Colour + Option.',pricing)+sectionBox('variants','Exact options','Quick-add options, then set exact quantity, rate, barcode, visibility and image.',variant)+sectionBox('subitems','Linked subitems','Attach matching reusable add-ons such as shorts, pants or accessories.',subitems)+'<div class="editor-savebar"><button type="button" class="ghost-btn" data-action="cancel-product">Cancel</button><button class="primary-btn" type="submit">Save ready-made product</button></div></form></section>';
  }
  function categoriesView(){
    const readyEdit=state.categoryEditor?state.categories.find(c=>c.id===state.categoryEditor):null;
    const customEdit=state.customCategoryEditor?state.customCatalogCategories.find(c=>c.id===state.customCategoryEditor):null;
    const editing=readyEdit||customEdit,type=customEdit?'custom':readyEdit?'ready':state.categoryType||'ready';
    return '<section class="clean-card simple-workspace category-manager-page"><div class="panel-head"><div><p class="tag">CATEGORY MANAGER</p><h1>Categories</h1><p>Create a category, choose its section, then add products from the separate item pages.</p></div></div><form id="unifiedCategoryForm" class="category-type-form"><div class="category-type-picker"><label class="'+(type==='ready'?'active':'')+'"><input type="radio" name="category_type" value="ready" '+(type==='ready'?'checked':'')+' '+(editing?'disabled':'')+'><span><b>Ready Made</b><small>Normal stock catalogue category</small></span></label><label class="'+(type==='custom'?'active':'')+'"><input type="radio" name="category_type" value="custom" '+(type==='custom'?'checked':'')+' '+(editing?'disabled':'')+'><span><b>Customizable</b><small>Customization idea category</small></span></label></div><div class="editor-grid category-create-grid"><label>Category name<input name="name" value="'+esc(editing?.name||'')+'" placeholder="Category name" required></label><label class="span2">Short description<input name="description" value="'+esc(customEdit?.description||readyEdit?.subtitle||'')+'" placeholder="Short description"></label><label>Category image<input name="image" type="file" accept="image/*"></label><div class="category-form-actions"><button class="primary-btn" type="submit">'+(editing?'Save category':'Add category')+'</button>'+(editing?'<button type="button" class="ghost-btn" data-action="cancel-unified-category-edit">Cancel</button>':'')+'</div></div></form><div class="category-section-split"><section><div class="simple-subheading"><div><b>Ready Made categories</b><span>'+state.categories.length+' categories</span></div></div><div class="category-admin-grid simple-category-grid">'+(state.categories.length?state.categories.map(c=>'<article><div class="category-admin-photo image-loading-shell">'+img(c.image_url,c.name)+'</div><div><b>'+esc(c.name)+'</b><small>'+esc(c.subtitle||'')+'</small></div><div class="row-actions"><button data-action="edit-category" data-id="'+c.id+'">Edit</button>'+(canDeleteStructure()?'<button class="danger-link" data-action="delete-category" data-id="'+c.id+'">Delete</button>':'')+'</div>'+(requested==='admin'?'<div class="subcategory-box"><b>Subcategories</b>'+state.subcategories.filter(s=>s.category_id===c.id).map(sc=>'<span>'+esc(sc.name)+'<button data-action="delete-subcategory" data-id="'+sc.id+'">×</button></span>').join('')+'<form data-subcategory-form="'+c.id+'"><input name="name" placeholder="Add subcategory" required><button>+</button></form></div>':'')+'</article>').join(''):'<div class="empty-admin">No Ready Made categories yet.</div>')+'</div></section><section><div class="simple-subheading"><div><b>Customizable categories</b><span>'+state.customCatalogCategories.length+' categories</span></div></div><div class="custom-admin-category-grid simple-category-grid">'+(state.customCatalogCategories.length?state.customCatalogCategories.map(c=>{const items=state.customCatalogItems.filter(i=>i.category_id===c.id);return '<article class="custom-admin-category-card"><div class="custom-admin-category-image image-loading-shell">'+img(c.image_url,c.name)+'</div><div class="custom-admin-category-copy"><b>'+esc(c.name)+'</b><small>'+esc(c.description||'No description')+'</small><span>'+items.length+' item'+(items.length===1?'':'s')+'</span></div><div class="row-actions"><button data-action="edit-custom-category" data-id="'+c.id+'">Edit</button>'+(canDeleteStructure()?'<button class="danger-link" data-action="delete-custom-category" data-id="'+c.id+'">Delete</button>':'')+'</div></article>';}).join(''):'<div class="empty-admin">No Customizable categories yet.</div>')+'</div></section></div></section>';
  }
  function blankCustomItem(){return{id:'',category_id:state.customCatalogCategories[0]?.id||'',title:'',description:'',rate:null,images:[],active:true,sort_order:0};}
  function customCatalogView(){
    if(!state.customSchemaReady)return '<section class="clean-card"><div class="panel-head"><div><p class="tag">CUSTOM CATALOGUE</p><h1>Database update required</h1><p>Run the latest included Supabase SQL update, then refresh.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh</button></div></section>';
    if(state.customItemEditor)return customItemEditorView();
    return '<section class="clean-card custom-catalog-admin simple-workspace"><div class="panel-head"><div><p class="tag">CUSTOM CATALOGUE</p><h1>Custom Catalogue items</h1><p>Customization reference items only. Categories are created from the separate Categories page.</p></div><button class="submit-small" data-action="new-custom-item" '+(!state.customCatalogCategories.length?'disabled':'')+'>+ Add Custom Item</button></div>'+(!state.customCatalogCategories.length?'<div class="simple-callout"><b>Add a Customizable category first.</b><button data-view="categories">Open Categories</button></div>':'')+'<div class="admin-product-list">'+(state.customCatalogItems.length?state.customCatalogItems.map(i=>{const c=state.customCatalogCategories.find(x=>x.id===i.category_id),hasRate=i.rate!==null&&i.rate!==undefined&&i.rate!=='';return '<article class="admin-product custom-admin-item"><div class="admin-list-image image-loading-shell">'+img(i.images?.[0],i.title)+'</div><div class="admin-product-copy"><span class="audience-pill">CUSTOM</span><b>'+esc(i.title||'Untitled')+'</b><small>'+esc(c?.name||'Uncategorized')+'</small></div><div class="admin-product-meta"><b>'+Number(i.images?.length||0)+' images</b><small>'+(i.active===false?'Hidden':'Visible')+'</small></div><div class="admin-product-price"><b>'+(hasRate?money(i.rate):'No rate')+'</b><small>'+(hasRate?'Optional display rate':'Enquiry only')+'</small></div><div class="row-actions"><button data-action="edit-custom-item" data-id="'+i.id+'">Edit</button>'+(canDeleteStructure()?'<button class="danger-link" data-action="delete-custom-item" data-id="'+i.id+'">Delete</button>':'')+'</div></article>';}).join(''):'<div class="empty-admin">No Custom Catalogue items yet.</div>')+'</div></section>';
  }
  function customItemEditorView(){const i=state.customItemEditor,rate=i.rate===null||i.rate===undefined?'':i.rate;return '<section class="clean-card editor-page simple-workspace"><div class="panel-head"><div><p class="tag">'+(i.id?'EDIT CUSTOM ITEM':'NEW CUSTOM ITEM')+'</p><h1>'+esc(i.title||'Custom catalogue item')+'</h1><p>Reference images, description and an optional rate.</p></div><button class="ghost-btn" data-action="close-custom-item">Back</button></div><form id="customItemEditor"><div class="portal-edit-section editing simple-editor-section"><fieldset><div class="editor-grid"><label>Item title<input data-ci="title" value="'+esc(i.title||'')+'" required></label><label>Category<select data-ci="category_id" required><option value="">Select category</option>'+state.customCatalogCategories.map(c=>'<option value="'+c.id+'" '+(i.category_id===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label>Rate <small>(optional)</small><input data-ci="rate" type="number" min="0" step="0.01" value="'+esc(rate)+'" placeholder="Leave blank to hide rate"></label><label class="admin-check-label"><input data-ci="active" type="checkbox" '+(i.active!==false?'checked':'')+'> Visible</label><label class="span2">Description<textarea data-ci="description" rows="6" placeholder="Describe the style and what can be customized">'+esc(i.description||'')+'</textarea></label></div><div class="upload-zone"><input id="customItemImages" type="file" accept="image/*" multiple><div><b>Upload item images</b><small>Any image size or ratio is accepted. The detailed customer page shows the full image without cropping.</small></div></div><div class="image-preview-grid">'+(i.images||[]).map((src,n)=>'<div class="image-chip">'+img(src,i.title)+'<button type="button" data-remove-custom-image="'+n+'">×</button></div>').join('')+'</div></fieldset></div><div class="editor-savebar"><button type="button" class="ghost-btn" data-action="close-custom-item">Cancel</button><button class="primary-btn" type="submit">Save Custom Item</button></div></form></section>';}
  function b2bList(){const q=state.query.trim().toLowerCase(),cat=state.b2bCategoryFilter;return state.products.filter(p=>p.audience==='b2b'&&(!cat||p.categoryId===cat)&&(!q||[p.name,p.code,p.category,p.description].join(' ').toLowerCase().includes(q)));}
  function blankB2B(){return{id:'',name:'',description:'',code:'',barcode:'',categoryId:state.categories[0]?.id||'',subcategoryId:'',audience:'b2b',price:0,mrp:0,type:'Simple',optionTitle:'Option',stock:0,images:[],variants:[],subItemIds:[],active:true,askForPrice:true};}
  function b2bView(){
    if(state.b2bEditor)return b2bEditorView();
    const list=b2bList();
    return '<section class="clean-card simple-workspace"><div class="panel-head"><div><p class="tag">B2B</p><h1>B2B catalogue</h1><p>Simple wholesale showcase: category, images, description and enquiry button. No stock, variants or price setup.</p></div><button class="submit-small" data-action="new-b2b">+ Add B2B item</button></div><div class="list-controls ready-list-controls"><select id="b2bCategoryFilter"><option value="">All categories</option>'+state.categories.map(c=>'<option value="'+c.id+'" '+(state.b2bCategoryFilter===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select><input id="b2bSearch" type="search" value="'+esc(state.query)+'" placeholder="Search B2B item or category"><span>'+list.length+' item'+(list.length===1?'':'s')+'</span></div><div class="admin-product-list">'+(list.length?list.map(p=>'<article class="admin-product b2b-admin-product"><div class="admin-list-image image-loading-shell">'+img(p.image||p.images?.[0],p.name)+'</div><div class="admin-product-copy"><span class="audience-pill b2b">B2B</span><b>'+esc(p.name||'Untitled')+'</b><small>'+esc(p.category||'No category')+'</small></div><div class="admin-product-meta"><b>'+Number(p.images?.length||0)+' images</b><small>Enquiry only</small></div><div class="row-actions"><button data-action="edit-b2b" data-id="'+p.id+'">Edit</button>'+(canDeleteProduct()?'<button class="danger-link" data-action="delete-product" data-id="'+p.id+'">Delete</button>':'')+'</div></article>').join(''):'<div class="empty-admin">No B2B items yet.</div>')+'</div></section>';
  }
  function b2bEditorView(){const p=state.b2bEditor;return '<section class="clean-card editor-page simple-workspace"><div class="panel-head"><div><p class="tag">'+(p.id?'EDIT B2B ITEM':'NEW B2B ITEM')+'</p><h1>'+esc(p.name||'B2B item')+'</h1><p>Keep it simple: category, images and description. Customers only get an enquiry button.</p></div><button class="ghost-btn" data-action="close-b2b">Back</button></div><form id="b2bEditor"><div class="portal-edit-section editing simple-editor-section"><fieldset><div class="editor-grid"><label>Item name<input data-bi="name" value="'+esc(p.name||'')+'" required></label><label>Category<select data-bi="categoryId" required><option value="">Select category</option>'+state.categories.map(c=>'<option value="'+c.id+'" '+(p.categoryId===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label class="span2">Description<textarea data-bi="description" rows="5" placeholder="Describe this B2B item">'+esc(p.description||'')+'</textarea></label></div><div class="upload-zone"><input id="b2bImages" type="file" accept="image/*" multiple><div><b>Upload item images</b><small>Add one or more catalogue images. No stock or pricing is required.</small></div></div><div class="image-preview-grid">'+(p.images||[]).map((src,n)=>'<div class="image-chip image-loading-shell">'+img(src,p.name)+'<button type="button" data-remove-b2b-image="'+n+'">×</button></div>').join('')+'</div></fieldset></div><div class="editor-savebar"><button type="button" class="ghost-btn" data-action="close-b2b">Cancel</button><button class="primary-btn" type="submit">Save B2B item</button></div></form></section>';}
  function syncB2BEditor(){if(!state.b2bEditor)return;root.querySelectorAll('[data-bi]').forEach(el=>state.b2bEditor[el.dataset.bi]=el.value);}
  async function saveB2B(e){e.preventDefault();syncB2BEditor();const p=state.b2bEditor;if(!p.name.trim()){notify('Item name is required.');return;}if(!p.categoryId){notify('Select a category.');return;}p.audience='b2b';p.type='Simple';p.price=0;p.mrp=0;p.stock=0;p.variants=[];p.subItemIds=[];p.askForPrice=true;try{await B.upsertProduct(p);state.b2bEditor=null;await loadAll();notify('B2B item saved.');}catch(err){notify(err.message||'Could not save B2B item');}}
  function enquiriesView(){const q=state.enquiryQuery.trim().toLowerCase(),list=state.enquiries.filter(e=>{const c=e.customers||{},p=e.payload||{};return !q||[c.name,c.phone,c.business_name,c.job_title,p.itemTitle,p.categoryName].join(' ').toLowerCase().includes(q);});return '<section class="clean-card enquiry-admin-page simple-workspace"><div class="panel-head"><div><p class="tag">CUSTOM ENQUIRIES</p><h1>Enquiries</h1><p>Custom item + verified customer contact details.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh</button></div><div class="list-controls simple-enquiry-search"><input id="enquirySearch" type="search" value="'+esc(state.enquiryQuery)+'" placeholder="Search name, phone, category or item"><span>'+list.length+' enquir'+(list.length===1?'y':'ies')+'</span></div><div class="enquiry-admin-list">'+(list.length?list.map(e=>{const c=e.customers||{},p=e.payload||{},hasRate=p.itemRate!==null&&p.itemRate!==undefined&&p.itemRate!=='';return '<article class="enquiry-admin-card"><div class="enquiry-item-image">'+img(p.image,p.itemTitle)+'</div><div class="enquiry-item-copy"><span class="audience-pill">'+esc(p.categoryName||'CUSTOM CATALOGUE')+'</span><h2>'+esc(p.itemTitle||'Customization enquiry')+'</h2>'+(hasRate?'<b class="enquiry-rate">'+money(p.itemRate)+'</b>':'')+'<p>'+esc(p.itemDescription||'')+'</p><small>'+new Date(e.created_at).toLocaleString()+'</small>'+(p.itemId?'<a href="index.html?customItem='+encodeURIComponent(p.itemId)+'#customItem" target="_blank" rel="noopener">Open item ↗</a>':'')+'</div><div class="enquiry-customer-details"><h3>Customer</h3><dl><div><dt>Name</dt><dd>'+esc(c.name||'—')+'</dd></div><div><dt>Mobile</dt><dd>'+esc(c.phone||'—')+'</dd></div><div><dt>Business</dt><dd>'+esc(c.business_name||'—')+'</dd></div><div><dt>Role</dt><dd>'+esc(c.job_title||'—')+'</dd></div></dl></div></article>';}).join(''):'<div class="empty-admin">No Custom Catalogue enquiries yet.</div>')+'</div></section>';}
  function syncCustomItemEditor(){if(!state.customItemEditor)return;root.querySelectorAll('[data-ci]').forEach(el=>{let v=el.type==='checkbox'?el.checked:el.value;if(el.dataset.ci==='sort_order')v=Number(v||0);if(el.dataset.ci==='rate')v=String(v).trim()===''?null:Number(v);state.customItemEditor[el.dataset.ci]=v;});}
  async function saveCustomItem(e){e.preventDefault();syncCustomItemEditor();const i=state.customItemEditor;if(!String(i.title||'').trim()){notify('Item title is required.');return;}if(!i.category_id){notify('Select a category.');return;}try{const payload={id:i.id||undefined,category_id:i.category_id,title:String(i.title).trim(),description:String(i.description||'').trim(),rate:(i.rate===null||i.rate===undefined||i.rate==='')?null:Number(i.rate),images:i.images||[],active:i.active!==false,sort_order:Number(i.sort_order||0),updated_at:new Date().toISOString()};const r=await sb().from('custom_catalog_items').upsert(payload).select().single();if(r.error)throw r.error;state.customItemEditor=null;await loadAll();notify('Custom catalogue item saved.');}catch(err){notify(err.message||'Could not save catalogue item');}}
  function blankSub(){return{id:'',name:'',code:'',barcode:'',price:0,optionTitle:'Size',type:'Colour + Option',images:[],variants:[{color:'',size:'',stock:0,price:0,barcode:'',image:'',active:true}],active:true};}
  function inferSubType(si){const vv=si?.variants||[];if(!vv.length)return'One Option';return vv.some(v=>String(v.color||'').trim())?'Colour + Option':'One Option';}
  function subVariantRowsHtml(si){const variants=si.variants||[],colorMode=si.type==='Colour + Option';return '<div class="variant-quick-builder"><div class="variant-quick-copy"><b>Quick add subitem options</b><small>Add sizes/options in one go, then set exact quantity, price, barcode, visibility and image.</small></div><div class="variant-quick-grid">'+(colorMode?'<label>Colour<input id="subQuickColor" placeholder="Black / White"></label>':'')+'<label>'+esc(si.optionTitle||'Option')+' values<input id="subQuickValues" placeholder="S, M, L, XL"></label><label>Qty each<input id="subQuickQty" type="number" min="0" value="0"></label><label>Rate each<input id="subQuickPrice" type="number" min="0" step="0.01" value="'+Number(si.price||0)+'"></label><button type="button" data-action="quick-add-sub-variants">Add options</button></div></div><div class="variant-admin-list enhanced">'+(variants.length?variants.map((v,i)=>'<article class="enhanced-variant-row"><div class="enhanced-variant-title"><b>'+esc([v.color,v.size].filter(Boolean).join(' · ')||('Option '+(i+1)))+'</b><button type="button" data-remove-sub-variant="'+i+'">Remove</button></div><div class="enhanced-variant-fields">'+(colorMode?'<label>Colour<input data-sv="color" data-i="'+i+'" value="'+esc(v.color||'')+'" placeholder="Black"></label>':'<input type="hidden" data-sv="color" data-i="'+i+'" value="">')+'<label>'+esc(si.optionTitle||'Option')+'<input data-sv="size" data-i="'+i+'" value="'+esc(v.size||'')+'" placeholder="M"></label><label>Quantity<input data-sv="stock" data-i="'+i+'" type="number" min="0" value="'+Number(v.stock||0)+'"></label><label>Final rate<input data-sv="price" data-i="'+i+'" type="number" min="0" step="0.01" value="'+Number(v.price??si.price??0)+'"></label><label>Barcode<input data-sv="barcode" data-i="'+i+'" value="'+esc(v.barcode||'')+'" placeholder="Optional"></label></div><div class="variant-image-visibility"><label class="variant-active-toggle"><input type="checkbox" data-sv-active="'+i+'" '+(v.active!==false?'checked':'')+'><span><b>Available</b><small>Turn off to hide this exact option.</small></span></label><div class="variant-image-picker">'+(v.image?img(v.image,[v.color,v.size].filter(Boolean).join(' ')):'<div class="variant-image-placeholder">No separate image</div>')+'<label><span>'+(v.image?'Replace image':'Add option image')+'</span><input type="file" accept="image/*" data-sub-variant-image-upload="'+i+'"></label>'+(v.image?'<button type="button" data-clear-sub-variant-image="'+i+'">Use main image</button>':'')+'</div></div></article>').join(''):'<div class="variant-empty-note"><b>No options yet</b><span>Use Quick add or Add one option.</span></div>')+'</div><button class="add-single-variant" type="button" data-action="add-sub-variant">+ Add one option</button>';}
  function subitemsView(){
    if(state.subEditor){const si=state.subEditor;return '<section class="clean-card editor-page"><div class="panel-head"><div><p class="tag">REUSABLE SUBITEM</p><h1>'+esc(si.name||'Add subitem')+'</h1><p>Wellone-style reusable add-on: images, option groups, exact stock, separate rate, barcode and option image.</p></div><button data-action="close-sub-editor">Back</button></div><form id="subitemEditor"><div class="portal-edit-section editing"><fieldset><div class="editor-grid"><label>Name<input data-si="name" value="'+esc(si.name||'')+'" required></label><label>Code<input data-si="code" value="'+esc(si.code||'')+'" placeholder="Blank = random code"></label><label>Barcode<input data-si="barcode" value="'+esc(si.barcode||'')+'"></label><label>Base price<input data-si="price" type="number" min="0" step="0.01" value="'+Number(si.price||0)+'"></label><label>Subitem type<select data-si="type"><option '+(si.type==='One Option'?'selected':'')+'>One Option</option><option '+(si.type==='Colour + Option'?'selected':'')+'>Colour + Option</option></select></label><label>Option title<input data-si="optionTitle" value="'+esc(si.optionTitle||'Size')+'" placeholder="Size / Pack"></label></div><div class="upload-zone"><input id="subImages" type="file" accept="image/*" multiple><div><b>Subitem images</b><small>Main images are inherited unless an exact option has its own image.</small></div></div><div class="image-preview-grid">'+(si.images||[]).map((src,i)=>'<div class="image-chip">'+img(src,si.name)+'<button type="button" data-remove-sub-image="'+i+'">×</button></div>').join('')+'</div>'+subVariantRowsHtml(si)+'</fieldset></div><div class="editor-savebar"><button type="button" class="ghost-btn" data-action="close-sub-editor">Cancel</button><button class="primary-btn">Save subitem</button></div></form></section>';}
    return '<section class="clean-card"><div class="panel-head"><div><p class="tag">REUSABLE ADD-ONS</p><h1>Subitems</h1><p>Create matching shorts, pants, sleeves or accessories once and attach them to unlimited Ready Made products.</p></div><button class="submit-small" data-action="new-subitem">+ Create subitem</button></div><div class="admin-product-list">'+(state.subitems.length?state.subitems.map(si=>'<article class="admin-product">'+img(si.images?.[0],si.name)+'<div class="admin-product-copy"><span class="audience-pill">SUBITEM</span><b>'+esc(si.name)+'</b><small>'+esc(si.code||'')+(si.barcode?' · '+esc(si.barcode):'')+'</small></div><div class="admin-product-meta"><b>'+(si.variants||[]).length+' options</b><small>'+((si.variants||[]).reduce((n,v)=>n+Number(v.stock||0),0))+' stock</small></div><div class="admin-product-price"><b>'+money(si.price||0)+'</b><small>'+esc(si.option_title||'Size')+'</small></div><div class="row-actions"><button data-action="edit-subitem" data-id="'+si.id+'">Edit</button></div></article>').join(''):'<div class="empty-admin">No subitems yet.</div>')+'</div></section>';
  }
  function stockRows(){
    const rows=[];
    state.products.forEach(p=>{
      const base={name:p.name,code:p.code||'',itemBarcode:p.barcode||'',category:p.category||'',subcategory:p.subcategory||'',image:p.image||p.images?.[0]||''};
      if(p.variants?.length)p.variants.forEach(v=>rows.push({...base,kind:'product-variant',id:v.id,variantBarcode:v.barcode||'',option:[v.color,v.size].filter(Boolean).join(' · ')||'Option',stock:Number(v.stock||0)}));
      else rows.push({...base,kind:'product',id:p.id,variantBarcode:'',option:'Simple product',stock:Number(p.stock||0)});
    });
    state.subitems.forEach(si=>(si.variants||[]).forEach(v=>rows.push({kind:'subitem',id:v.id,name:si.name,code:si.code||'',itemBarcode:si.barcode||'',variantBarcode:v.barcode||'',category:'Subitem',subcategory:'',image:si.images?.[0]||'',option:[v.color,v.size].filter(Boolean).join(' · ')||'Subitem option',stock:Number(v.stock||0)})));
    return rows;
  }
  function stockView(){
    const q=state.query.trim().toLowerCase(),rows=stockRows().filter(r=>!q||[r.name,r.code,r.itemBarcode,r.variantBarcode,r.option,r.category,r.subcategory].join(' ').toLowerCase().includes(q));
    if(requested==='staff')return '<section class="clean-card staff-stock-card"><div class="panel-head"><div><p class="tag">SALES STOCK</p><h1>Mark items as sold</h1><p>Search by product name, item code, barcode, category, colour or size. Choose the exact variant and enter the sold quantity.</p></div></div><div class="list-controls"><input id="stockSearch" type="search" value="'+esc(state.query)+'" placeholder="Search name, code, barcode, colour, size…"><span>'+rows.length+' result'+(rows.length===1?'':'s')+'</span></div><div class="staff-stock-list">'+(rows.length?rows.map(r=>'<article class="staff-stock-item">'+img(r.image,r.name)+'<div class="staff-stock-main"><b>'+esc(r.name)+'</b><span>'+esc(r.option)+'</span><small>'+esc([r.code,r.variantBarcode||r.itemBarcode,r.category,r.subcategory].filter(Boolean).join(' · '))+'</small></div><div class="staff-stock-count"><small>Available</small><strong class="'+(r.stock<=5?'low':'')+'">'+r.stock+'</strong></div><div class="staff-sold-action"><input type="number" min="1" max="'+Math.max(1,r.stock)+'" value="1" data-stock-amount="'+r.id+'" '+(r.stock<=0?'disabled':'')+'><button data-stock-sold="'+r.id+'" data-kind="'+r.kind+'" '+(r.stock<=0?'disabled':'')+'>'+(r.stock<=0?'Out of stock':'Mark sold')+'</button></div></article>').join(''):'<div class="empty-admin">No matching stock item.</div>')+'</div></section>';
    return '<section class="clean-card"><div class="panel-head"><div><p class="tag">LIVE INVENTORY</p><h1>Stock desk</h1><p>Admin adjustments are written to stock movement history.</p></div></div><div class="list-controls"><input id="stockSearch" type="search" value="'+esc(state.query)+'" placeholder="Search name, code, barcode, colour or size"></div><div class="stock-table"><div class="stock-row head"><span>Item</span><span>Option</span><span>Stock</span><span>Adjust</span></div>'+rows.map(r=>'<div class="stock-row"><span><b>'+esc(r.name)+'</b><small>'+esc([r.code,r.variantBarcode||r.itemBarcode].filter(Boolean).join(' · '))+'</small></span><span>'+esc(r.option)+'</span><strong class="'+(r.stock<=5?'low':'')+'">'+r.stock+'</strong><span class="stock-adjust"><input type="number" min="1" value="1" data-stock-amount="'+r.id+'"><button data-stock-change="'+r.id+'" data-kind="'+r.kind+'" data-sign="1">+</button><button data-stock-change="'+r.id+'" data-kind="'+r.kind+'" data-sign="-1">−</button></span></div>').join('')+'</div></section>';
  }
  function orderLines(id){return state.orderItems.filter(i=>i.order_id===id);}
  function ordersView(){const q=state.orderQuery.trim().toLowerCase(),list=state.orders.filter(o=>(state.orderFilter==='All'||o.status===state.orderFilter)&&(!q||[o.order_code,o.customer_name,o.phone,o.business].join(' ').toLowerCase().includes(q)));const statuses=['Confirmed','Processing','Ready','Dispatched','Completed','Cancelled'];return '<section class="clean-card"><div class="panel-head"><div><p class="tag">ORDER RECEIVING</p><h1>Orders</h1><p>Exact size quantities, subitems and custom design data are kept with each order.</p></div></div><div class="order-toolbar"><input id="orderSearch" value="'+esc(state.orderQuery)+'" placeholder="Search order, customer or phone"><div>'+['All',...statuses].map(s=>'<button data-order-filter="'+s+'" class="'+(state.orderFilter===s?'active':'')+'">'+s+'</button>').join('')+'</div></div><div class="portal-order-list">'+(list.length?list.map(o=>{const lines=orderLines(o.id);return '<article class="portal-order"><header><div><span>#'+esc(o.order_code)+'</span><h2>'+esc(o.customer_name||o.business||'Customer')+'</h2><small>'+esc(o.phone)+' · '+new Date(o.created_at).toLocaleString()+'</small></div><div><strong>'+money(o.total||0)+'</strong>'+(canOrderStatus()?'<select data-order-status="'+o.id+'">'+statuses.map(s=>'<option '+(o.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select>':'<b>'+esc(o.status)+'</b>')+'</div></header><div class="portal-order-lines">'+lines.map(l=>'<div><span><b>'+esc(l.item_name)+'</b><small>'+esc(l.item_code||'')+' · '+esc([l.color,l.size].filter(Boolean).join(' · ')||l.item_type)+'</small></span><b>× '+l.qty+'</b><strong>'+money(Number(l.unit_price||0)*Number(l.qty||0))+'</strong>'+(l.design_json?'<details><summary>Design / roster</summary><pre>'+esc(JSON.stringify(l.design_json,null,2))+'</pre></details>':'')+'</div>').join('')+'</div><footer><span>'+esc(o.delivery||'')+'</span><span>'+esc(o.payment||'')+'</span><span>'+esc(o.address||'')+'</span></footer></article>';}).join(''):'<div class="empty-admin">No matching orders.</div>')+'</div></section>';}
  function customerOrderCount(id){return state.orders.filter(o=>o.customer_id===id).length;}
  function customerCart(id){return state.carts.find(c=>c.customer_id===id)||null;}
  function customersView(){
    const q=state.customerQuery.trim().toLowerCase(),list=state.customers.filter(c=>!q||[c.name,c.phone,c.business_name,c.job_title].join(' ').toLowerCase().includes(q));
    return '<section class="clean-card"><div class="panel-head"><div><p class="tag">CUSTOMER ACCOUNTS</p><h1>Customers</h1><p>Each verified phone number stays connected to one customer, profile and order history.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh</button></div><div class="list-controls"><input id="customerSearch" type="search" value="'+esc(state.customerQuery)+'" placeholder="Search name, phone, business or role"><span>'+list.length+' customer'+(list.length===1?'':'s')+'</span></div><div class="customer-admin-list">'+(list.length?list.map(c=>{const cart=customerCart(c.id),orders=customerOrderCount(c.id);return '<article class="customer-admin-card"><div class="customer-avatar">'+esc((c.name||'?').slice(0,1).toUpperCase())+'</div><div class="customer-main"><b>'+esc(c.name||'Name not set')+'</b><span>'+esc(c.phone||'')+'</span><small>'+esc([c.job_title,c.business_name].filter(Boolean).join(' · ')||'No business details')+'</small></div><div class="customer-stats"><span><b>'+orders+'</b><small>orders</small></span><span><b>'+Number(cart?.piece_count||0)+'</b><small>cart pcs</small></span></div><div class="customer-time"><small>Last seen</small><b>'+new Date(c.last_seen_at||c.created_at).toLocaleString()+'</b><small>Joined '+new Date(c.created_at).toLocaleDateString()+'</small></div></article>';}).join(''):'<div class="empty-admin">No customers yet.</div>')+'</div></section>';
  }
  function cartItemSummary(item){const opts=[];(item.bulkLines||[]).forEach(l=>{if(Number(l.qty||0)>0)opts.push([l.color,l.size].filter(Boolean).join(' · ')+' × '+l.qty)});(item.subitems||[]).forEach(si=>(si.lines||[]).forEach(l=>{if(Number(l.qty||0)>0)opts.push((si.name||'Subitem')+' '+[l.color,l.size].filter(Boolean).join(' · ')+' × '+l.qty)}));if(item.sizeQuantities)Object.entries(item.sizeQuantities).forEach(([size,qty])=>{if(Number(qty)>0)opts.push(size+' × '+qty)});return '<div class="live-cart-item"><div><b>'+esc(item.name||'Item')+'</b><small>'+esc([item.code,item.detail].filter(Boolean).join(' · '))+'</small>'+(opts.length?'<em>'+opts.slice(0,10).map(esc).join(' / ')+'</em>':'')+'</div><span>× '+Number(item.qty||1)+'</span><strong>'+money(item.total||0)+'</strong></div>';}
  function cartsView(){
    const list=state.carts.filter(c=>Number(c.piece_count||0)>0);
    return '<section class="clean-card"><div class="panel-head"><div><p class="tag">LIVE CUSTOMER CARTS</p><h1>Who added what</h1><p>Shows the latest saved cart for each verified customer. Updates automatically while the portal is open.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh now</button></div><div class="live-cart-list">'+(list.length?list.map(c=>'<article class="live-cart-card"><header><div><b>'+esc(c.customers?.name||'Customer')+'</b><span>'+esc(c.customers?.phone||'')+'</span><small>'+esc([c.customers?.job_title,c.customers?.business_name].filter(Boolean).join(' · '))+'</small></div><div><strong>'+Number(c.piece_count||0)+' pcs</strong><b>'+money(c.total||0)+'</b><small>'+new Date(c.updated_at).toLocaleString()+'</small></div></header><div class="live-cart-items">'+((c.items||[]).length?(c.items||[]).map(cartItemSummary).join(''):'<div class="empty-admin">Cart has no item details.</div>')+'</div></article>').join(''):'<div class="empty-admin">No verified customer has items in cart right now.</div>')+'</div></section>';
  }
  function activityView(){return '<section class="clean-card"><div class="panel-head"><div><p class="tag">VERIFIED CUSTOMER ACTIVITY</p><h1>Customer activity</h1><p>Login, cart, checkout, profile and order actions recorded after OTP verification.</p></div><button class="ghost-btn" data-action="refresh-data">Refresh</button></div><div class="activity-list">'+(state.activity.length?state.activity.map(a=>'<article><div><b>'+esc(a.event_type.replaceAll('_',' '))+'</b><small>'+new Date(a.created_at).toLocaleString()+'</small></div><span>'+esc(a.customers?.name||'')+'<small>'+esc(a.customers?.phone||'')+'</small></span><pre>'+esc(JSON.stringify(a.payload||{},null,2))+'</pre></article>').join(''):'<div class="empty-admin">No verified customer activity yet.</div>')+'</div></section>';}
  function accountsView(){const defaults=[['Admin','admin.html','adminhere','admin22'],['Management','management.html','managementhere','manage22'],['Staff','staff.html','staffhere','staff220'],['Order Receiving','receiver.html','receiverhere','receiver22']];return '<section class="clean-card"><div class="panel-head"><div><p class="tag">ACCESS CONTROL</p><h1>Staff & management accounts</h1><p>Create Admin, Management, Staff and Order Receiving logins.</p></div></div><div class="default-access-box"><header><div><h3>Default portal access</h3><p>Create or reset the standard access IDs for every portal in one click.</p></div><button class="primary-btn" type="button" data-action="bootstrap-default-accounts">Create / reset access</button></header><div class="default-access-grid">'+defaults.map(x=>'<article><b>'+x[0]+'</b><span>'+x[1]+'</span><code>'+x[2]+' / '+x[3]+'</code></article>').join('')+'</div></div><form id="accountCreate" class="account-create"><label>Name<input name="name" required></label><label>Username<input name="username" required></label><label>Role<select name="role">'+roles.map(r=>'<option value="'+r+'">'+labels[r]+'</option>').join('')+'</select></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="primary-btn">Create account</button></form><div class="account-list">'+state.profiles.map(p=>'<article><div><b>'+esc(p.name)+'</b><small>@'+esc(p.username)+'</small></div><select data-account-role="'+p.id+'">'+roles.map(r=>'<option value="'+r+'" '+(p.role===r?'selected':'')+'>'+labels[r]+'</option>').join('')+'</select><label class="account-active"><input type="checkbox" data-account-active="'+p.id+'" '+(p.active?'checked':'')+'> Active</label><input type="password" data-account-password="'+p.id+'" placeholder="New password optional"><button data-action="save-account" data-id="'+p.id+'">Save</button></article>').join('')+'</div></section>';}

  function settingsView(){const shortcuts=requested==='admin'?'<div class="portal-shortcuts"><a href="management.html">Management</a><a href="staff.html">Stock / Staff</a><a href="receiver.html">Order Receiving</a></div>':'';return '<section class="clean-card portal-settings simple-workspace"><div class="panel-head"><div><p class="tag">SETTINGS</p><h1>Account</h1></div></div><div class="settings-profile-card"><div class="settings-avatar">'+esc((state.profile?.name||state.profile?.username||'?').slice(0,1).toUpperCase())+'</div><div><b>'+esc(state.profile?.name||labels[requested])+'</b><span>@'+esc(state.profile?.username||'')+'</span><small>'+esc(labels[state.profile?.role]||state.profile?.role||'')+'</small></div></div>'+shortcuts+'<div class="settings-actions"><button class="secondary-btn" data-action="refresh-data">Refresh data</button><button class="secondary-btn" data-action="open-store">Open customer site</button><button class="danger-settings-btn" data-action="logout">Sign out</button></div></section>';}

  async function loadAll(silent=false){
    if(!silent){state.loading=true;render();}state.error='';try{
      await B.hydrate();state.products=S.getProducts();
      const client=sb();
      const base=await Promise.all([client.from('categories').select('*').order('sort_order'),client.from('subcategories').select('*').order('sort_order'),B.listSubitems()]);
      if(base[0].error)throw base[0].error;if(base[1].error)throw base[1].error;
      state.categories=base[0].data||[];state.subcategories=base[1].data||[];state.subitems=base[2]||[];
      state.orders=[];state.orderItems=[];state.activity=[];state.customers=[];state.carts=[];state.profiles=[];state.enquiries=[];
      if(requested==='receiver'){
        const [orders,items]=await Promise.all([client.from('orders').select('*').order('created_at',{ascending:false}).limit(250),client.from('order_items').select('*').order('created_at',{ascending:true}).limit(1500)]);
        if(orders.error)throw orders.error;if(items.error)throw items.error;state.orders=orders.data||[];state.orderItems=items.data||[];
      }
      if(requested==='admin'||requested==='management'){
        const [cc,ci]=await Promise.all([client.from('custom_catalog_categories').select('*').order('sort_order'),client.from('custom_catalog_items').select('*').order('sort_order')]);
        state.customSchemaReady=!cc.error&&!ci.error;state.customCatalogCategories=cc.error?[]:(cc.data||[]);state.customCatalogItems=ci.error?[]:(ci.data||[]);
      }else{state.customCatalogCategories=[];state.customCatalogItems=[];}
      if(requested==='admin'){
        const enq=await client.from('customer_activity').select('*,customers(id,name,phone,business_name,job_title,created_at,last_seen_at)').eq('event_type','custom_catalog_enquiry').order('created_at',{ascending:false}).limit(1000);
        state.enquiries=enq.error?[]:(enq.data||[]);state.profiles=await B.listProfiles();
      }
    }catch(e){state.error=e.message||String(e);}finally{state.loading=false;render();}
  }
  function syncProductEditor(){if(!state.editor)return;root.querySelectorAll('[data-p]').forEach(el=>{let v=el.value;if(['price','mrp','stock'].includes(el.dataset.p))v=Number(v||0);state.editor[el.dataset.p]=v;});root.querySelectorAll('[data-v]').forEach(el=>{const i=Number(el.dataset.i);if(!state.editor.variants[i])return;let v=el.value;if(['stock','price'].includes(el.dataset.v))v=Number(v||0);state.editor.variants[i][el.dataset.v]=v;});root.querySelectorAll('[data-v-active]').forEach(el=>{const i=Number(el.dataset.vActive);if(state.editor.variants[i])state.editor.variants[i].active=el.checked;});state.editor.subItemIds=[...root.querySelectorAll('[data-sub-link]:checked')].map(x=>x.dataset.subLink);}
  function syncSubEditor(){if(!state.subEditor)return;root.querySelectorAll('[data-si]').forEach(el=>{let v=el.value;if(el.dataset.si==='price')v=Number(v||0);state.subEditor[el.dataset.si]=v;});root.querySelectorAll('[data-sv]').forEach(el=>{const i=Number(el.dataset.i);if(!state.subEditor.variants[i])return;let v=el.value;if(['stock','price'].includes(el.dataset.sv))v=Number(v||0);state.subEditor.variants[i][el.dataset.sv]=v;});root.querySelectorAll('[data-sv-active]').forEach(el=>{const i=Number(el.dataset.svActive);if(state.subEditor.variants[i])state.subEditor.variants[i].active=el.checked;});}
  const validManualCode=v=>/^(?=.*[A-Z])(?=.*[0-9])[A-Z0-9]{6}$/.test(String(v||'').trim().toUpperCase());
  async function saveProduct(e){e.preventDefault();syncProductEditor();const p=state.editor;p.audience='retail';if(!p.name.trim()){notify('Product name is required.');return;}if(!p.categoryId){notify('Select a category.');return;}if(!String(p.barcode||'').trim()&&String(p.code||'').trim()&&!validManualCode(p.code)){notify('Manual item code must be 6 characters with letters and numbers.');return;}if(p.type==='Simple')p.variants=[];else if(!(p.variants||[]).length){notify('Add at least one size/option row.');return;}try{await B.upsertProduct(p);state.editor=null;await loadAll();notify('Product saved.');}catch(err){notify(err.message||'Could not save product');}}
  async function saveSubitem(e){e.preventDefault();syncSubEditor();if(!state.subEditor.name.trim()){notify('Subitem name is required.');return;}if(!(state.subEditor.variants||[]).length){notify('Add at least one subitem option.');return;}if(!String(state.subEditor.barcode||'').trim()&&String(state.subEditor.code||'').trim()&&!validManualCode(state.subEditor.code)){notify('Manual item code must be 6 characters with letters and numbers.');return;}try{await B.upsertSubitem(state.subEditor);state.subEditor=null;await loadAll();notify('Subitem saved.');}catch(err){notify(err.message||'Could not save subitem');}}
  async function uploadMany(files,folder){const out=[];for(const f of files)out.push(await B.uploadImage(f,folder));return out;}
  async function adjustStock(id,kind,delta){try{const client=sb();const reason=requested==='staff'?'Staff marked as sold':'Admin stock adjustment';let r;if(kind==='product-variant')r=await client.rpc('adjust_stock',{p_variant:id,p_delta:delta,p_reason:reason});else if(kind==='product')r=await client.rpc('adjust_product_stock',{p_product:id,p_delta:delta,p_reason:reason});else r=await client.rpc('adjust_subitem_stock',{p_variant:id,p_delta:delta,p_reason:reason});if(r.error)throw r.error;await loadAll();notify(requested==='staff'?'Marked as sold.':'Stock updated.');}catch(e){notify(e.message||'Stock update failed');}}

  function bind(){
    root.querySelector('#portalLogin')?.addEventListener('submit',async e=>{e.preventDefault();state.error='';const fd=new FormData(e.currentTarget);try{state.profile=await B.staffSignIn(fd.get('username'),fd.get('password'));if(!roleOkay()){render();return;}await loadAll();}catch(err){state.error=err.message||'Login failed';render();}});
    root.querySelectorAll('[data-view]').forEach(x=>x.addEventListener('click',()=>{state.view=x.dataset.view;state.menu=false;state.editor=null;state.b2bEditor=null;state.subEditor=null;state.customItemEditor=null;state.categoryEditor=null;state.customCategoryEditor=null;state.query='';render();}));
    root.querySelector('[data-action="menu"]')?.addEventListener('click',()=>{state.menu=!state.menu;render();});
    root.querySelectorAll('[data-action="logout"]').forEach(x=>x.addEventListener('click',async()=>{await B.staffSignOut();state.profile=null;render();}));
    root.querySelector('[data-action="open-store"]')?.addEventListener('click',()=>location.href='index.html');
    root.querySelectorAll('[data-action="refresh-data"]').forEach(x=>x.addEventListener('click',()=>loadAll(false)));
    root.querySelectorAll('input[name="category_type"]').forEach(x=>x.addEventListener('change',()=>{state.categoryType=x.value;render();}));
    root.querySelector('#unifiedCategoryForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),type=state.customCategoryEditor?'custom':state.categoryEditor?'ready':String(fd.get('category_type')||state.categoryType||'ready'),name=String(fd.get('name')||'').trim(),description=String(fd.get('description')||'').trim(),file=fd.get('image'),wasEditing=!!(state.categoryEditor||state.customCategoryEditor);if(!name){notify('Category name is required.');return;}try{if(type==='custom'){const old=state.customCatalogCategories.find(c=>c.id===state.customCategoryEditor),image=file?.size?await B.uploadImage(file,'custom-catalog/categories'):(old?.image_url||'');const payload={id:old?.id||undefined,name,description,image_url:image,sort_order:Number(old?.sort_order||0),active:true,updated_at:new Date().toISOString()};const r=await sb().from('custom_catalog_categories').upsert(payload).select().single();if(r.error)throw r.error;}else{const old=state.categories.find(c=>c.id===state.categoryEditor),image=file?.size?await B.uploadImage(file,'categories'):(old?.image_url||'');await B.upsertCategory({id:old?.id||undefined,name,image,sub:description,active:true,sort_order:Number(old?.sort_order||0)});}state.categoryEditor=null;state.customCategoryEditor=null;state.categoryType='ready';await loadAll();notify(wasEditing?'Category updated.':'Category added.');}catch(err){notify(err.message||'Could not save category');}});
    root.querySelector('[data-action="cancel-unified-category-edit"]')?.addEventListener('click',()=>{state.categoryEditor=null;state.customCategoryEditor=null;render();});
    root.querySelector('[data-action="new-product"]')?.addEventListener('click',()=>beginProduct(null));
    root.querySelectorAll('[data-action="edit-product"]').forEach(x=>x.addEventListener('click',()=>beginProduct(state.products.find(p=>p.id===x.dataset.id))));
    root.querySelector('[data-action="cancel-product"]')?.addEventListener('click',()=>{state.editor=null;render();});
    root.querySelectorAll('[data-edit-section]').forEach(x=>x.addEventListener('click',()=>{syncProductEditor();document.activeElement?.blur?.();state.editSections[x.dataset.editSection]=!state.editSections[x.dataset.editSection];render();}));
    root.querySelector('#productEditor')?.addEventListener('submit',saveProduct);
    root.querySelectorAll('[data-p]').forEach(x=>x.addEventListener('change',()=>{syncProductEditor();if(x.dataset.p==='categoryId')state.editor.subcategoryId='';if(['categoryId','type','optionTitle'].includes(x.dataset.p))render();}));
    root.querySelector('[data-action="add-variant"]')?.addEventListener('click',()=>{syncProductEditor();state.editor.variants.push({color:'',size:'',stock:0,price:Number(state.editor.price||0),barcode:'',image:'',active:true});render();});
    root.querySelector('[data-action=\"quick-add-variants\"]')?.addEventListener('click',()=>{syncProductEditor();const values=String(root.querySelector('#variantQuickValues')?.value||'').split(/[,\n|]+/).map(v=>v.trim()).filter(Boolean);if(!values.length){notify('Enter one or more option values.');return;}const color=state.editor.type==='Colour + Option'?String(root.querySelector('#variantQuickColor')?.value||'').trim():'';if(state.editor.type==='Colour + Option'&&!color){notify('Enter the colour for these options.');return;}const qty=Math.max(0,Number(root.querySelector('#variantQuickQty')?.value||0)),price=Number(root.querySelector('#variantQuickPrice')?.value||state.editor.price||0);values.forEach(size=>{const exists=state.editor.variants.some(v=>String(v.color||'').trim().toLowerCase()===color.toLowerCase()&&String(v.size||'').trim().toLowerCase()===size.toLowerCase());if(!exists)state.editor.variants.push({color,size,stock:qty,price,barcode:'',image:'',active:true});});render();});
    root.querySelectorAll('[data-remove-variant]').forEach(x=>x.addEventListener('click',()=>{syncProductEditor();state.editor.variants.splice(Number(x.dataset.removeVariant),1);render();}));
    root.querySelectorAll('[data-remove-product-image]').forEach(x=>x.addEventListener('click',()=>{syncProductEditor();state.editor.images.splice(Number(x.dataset.removeProductImage),1);render();}));
    root.querySelector('#productImages')?.addEventListener('change',async e=>{syncProductEditor();try{const urls=await uploadMany([...e.target.files],'products');state.editor.images.push(...urls);render();}catch(err){notify(err.message||'Upload failed');}});
    root.querySelectorAll('[data-variant-image-upload]').forEach(x=>x.addEventListener('change',async e=>{syncProductEditor();const i=Number(x.dataset.variantImageUpload),file=e.target.files?.[0];if(!file)return;try{const url=await B.uploadImage(file,'variants'),color=String(state.editor.variants[i]?.color||'').trim();if(state.editor.type==='Colour + Option'&&color)state.editor.variants.forEach(v=>{if(String(v.color||'').trim().toLowerCase()===color.toLowerCase())v.image=url;});else state.editor.variants[i].image=url;render();}catch(err){notify(err.message||'Option image upload failed');}}));
    root.querySelectorAll('[data-clear-variant-image]').forEach(x=>x.addEventListener('click',()=>{syncProductEditor();const i=Number(x.dataset.clearVariantImage),color=String(state.editor.variants[i]?.color||'').trim();if(state.editor.type==='Colour + Option'&&color)state.editor.variants.forEach(v=>{if(String(v.color||'').trim().toLowerCase()===color.toLowerCase())v.image='';});else if(state.editor.variants[i])state.editor.variants[i].image='';render();}));
    root.querySelector('[data-action="open-subitems"]')?.addEventListener('click',()=>{syncProductEditor();state.editor=null;state.view='subitems';render();});
    root.querySelectorAll('[data-action="delete-product"]').forEach(x=>x.addEventListener('click',async()=>{const p=state.products.find(v=>v.id===x.dataset.id);if(!p||!confirm('Delete '+p.name+'?'))return;try{await B.deleteProduct(p.id);await loadAll();notify('Product deleted.');}catch(e){notify(e.message||'Delete failed');}}));
    root.querySelector('#productCategoryFilter')?.addEventListener('change',e=>{state.productCategoryFilter=e.target.value;render();});
    root.querySelector('#productSearch')?.addEventListener('input',e=>{state.query=e.target.value;render();requestAnimationFrame(()=>{const n=root.querySelector('#productSearch');n?.focus();if(n)try{n.setSelectionRange(n.value.length,n.value.length);}catch(_){}});});
    root.querySelector('#stockSearch')?.addEventListener('input',e=>{state.query=e.target.value;render();requestAnimationFrame(()=>root.querySelector('#stockSearch')?.focus());});
    root.querySelector('#customerSearch')?.addEventListener('input',e=>{state.customerQuery=e.target.value;render();requestAnimationFrame(()=>{const n=root.querySelector('#customerSearch');n?.focus();if(n)try{n.setSelectionRange(n.value.length,n.value.length);}catch(_){}});});
    root.querySelectorAll('[data-stock-change]').forEach(x=>x.addEventListener('click',()=>{const amount=Math.max(1,Number(root.querySelector('[data-stock-amount="'+x.dataset.stockChange+'"]')?.value||1));adjustStock(x.dataset.stockChange,x.dataset.kind,amount*Number(x.dataset.sign));}));
    root.querySelectorAll('[data-stock-sold]').forEach(x=>x.addEventListener('click',()=>{const input=root.querySelector('[data-stock-amount="'+x.dataset.stockSold+'"]'),row=stockRows().find(r=>r.id===x.dataset.stockSold);const amount=Math.max(1,Number(input?.value||1));if(!row||row.stock<=0){notify('This item is out of stock.');return;}if(amount>row.stock){notify('Sold quantity cannot be more than available stock.');return;}adjustStock(x.dataset.stockSold,x.dataset.kind,-amount);}));

    root.querySelectorAll('[data-action="edit-category"]').forEach(x=>x.addEventListener('click',()=>{state.categoryEditor=x.dataset.id;state.customCategoryEditor=null;state.categoryType='ready';state.view='categories';render();}));
    
    root.querySelectorAll('[data-subcategory-form]').forEach(f=>f.addEventListener('submit',async e=>{e.preventDefault();const name=new FormData(f).get('name');try{const r=await sb().from('subcategories').insert({category_id:f.dataset.subcategoryForm,name:String(name).trim()});if(r.error)throw r.error;await loadAll();notify('Subcategory added.');}catch(err){notify(err.message||'Could not add subcategory');}}));
    root.querySelectorAll('[data-action="delete-category"]').forEach(x=>x.addEventListener('click',async()=>{if(!confirm('Delete this category? Products will remain but lose their category.'))return;const r=await sb().from('categories').delete().eq('id',x.dataset.id);if(r.error)notify(r.error.message);else{await loadAll();notify('Category deleted.');}}));
    root.querySelectorAll('[data-action="delete-subcategory"]').forEach(x=>x.addEventListener('click',async()=>{const r=await sb().from('subcategories').delete().eq('id',x.dataset.id);if(r.error)notify(r.error.message);else await loadAll();}));

    root.querySelectorAll('[data-action="edit-custom-category"]').forEach(x=>x.addEventListener('click',()=>{state.customCategoryEditor=x.dataset.id;state.categoryEditor=null;state.categoryType='custom';state.view='categories';render();}));
    
    root.querySelectorAll('[data-action="delete-custom-category"]').forEach(x=>x.addEventListener('click',async()=>{if(!confirm('Delete this customization category and all its items?'))return;const r=await sb().from('custom_catalog_categories').delete().eq('id',x.dataset.id);if(r.error)notify(r.error.message);else{state.customCategoryEditor=null;await loadAll();notify('Custom category deleted.');}}));
    root.querySelector('[data-action="new-custom-item"]')?.addEventListener('click',()=>{if(!state.customCatalogCategories.length){state.editor=null;state.view='categories';state.categoryType='custom';render();notify('Add a Customizable category first.');return;}state.editor=null;state.view='customCatalog';state.customItemEditor=blankCustomItem();render();});
    root.querySelectorAll('[data-action="edit-custom-item"]').forEach(x=>x.addEventListener('click',()=>{const raw=state.customCatalogItems.find(v=>v.id===x.dataset.id);state.customItemEditor={...structured(raw),images:[...(raw.images||[])]};render();}));
    root.querySelector('[data-action="close-custom-item"]')?.addEventListener('click',()=>{state.customItemEditor=null;render();});
    root.querySelector('#customItemEditor')?.addEventListener('submit',saveCustomItem);
    root.querySelectorAll('[data-ci]').forEach(x=>x.addEventListener('change',syncCustomItemEditor));
    root.querySelectorAll('[data-remove-custom-image]').forEach(x=>x.addEventListener('click',()=>{syncCustomItemEditor();state.customItemEditor.images.splice(Number(x.dataset.removeCustomImage),1);render();}));
    root.querySelector('#customItemImages')?.addEventListener('change',async e=>{syncCustomItemEditor();try{const urls=await uploadMany([...e.target.files],'custom-catalog/items');state.customItemEditor.images.push(...urls);render();}catch(err){notify(err.message||'Upload failed');}});
    root.querySelectorAll('[data-action="delete-custom-item"]').forEach(x=>x.addEventListener('click',async()=>{if(!confirm('Delete this customization catalogue item?'))return;const r=await sb().from('custom_catalog_items').delete().eq('id',x.dataset.id);if(r.error)notify(r.error.message);else{await loadAll();notify('Custom catalogue item deleted.');}}));
    root.querySelector('[data-action="new-b2b"]')?.addEventListener('click',()=>{if(!state.categories.length){state.view='categories';state.categoryType='ready';render();notify('Add a Ready Made category first.');return;}state.b2bEditor=blankB2B();render();});
    root.querySelectorAll('[data-action="edit-b2b"]').forEach(x=>x.addEventListener('click',()=>{const raw=state.products.find(p=>p.id===x.dataset.id&&p.audience==='b2b');if(!raw)return;state.b2bEditor={...blankB2B(),...structured(raw),images:[...(raw.images||[])],variants:[],subItemIds:[]};render();}));
    root.querySelector('[data-action="close-b2b"]')?.addEventListener('click',()=>{state.b2bEditor=null;render();});
    root.querySelector('#b2bEditor')?.addEventListener('submit',saveB2B);
    root.querySelectorAll('[data-bi]').forEach(x=>x.addEventListener('change',syncB2BEditor));
    root.querySelectorAll('[data-remove-b2b-image]').forEach(x=>x.addEventListener('click',()=>{syncB2BEditor();state.b2bEditor.images.splice(Number(x.dataset.removeB2bImage),1);render();}));
    root.querySelector('#b2bImages')?.addEventListener('change',async e=>{syncB2BEditor();try{const urls=await uploadMany([...e.target.files],'b2b');state.b2bEditor.images.push(...urls);render();}catch(err){notify(err.message||'Upload failed');}});
    root.querySelector('#b2bCategoryFilter')?.addEventListener('change',e=>{state.b2bCategoryFilter=e.target.value;render();});
    root.querySelector('#b2bSearch')?.addEventListener('input',e=>{state.query=e.target.value;render();requestAnimationFrame(()=>root.querySelector('#b2bSearch')?.focus());});
    root.querySelector('#enquirySearch')?.addEventListener('input',e=>{state.enquiryQuery=e.target.value;render();requestAnimationFrame(()=>{const n=root.querySelector('#enquirySearch');n?.focus();if(n)try{n.setSelectionRange(n.value.length,n.value.length);}catch(_){}});});

    root.querySelector('[data-action="new-subitem"]')?.addEventListener('click',()=>{state.subEditor=blankSub();render();});
    root.querySelectorAll('[data-action="edit-subitem"]').forEach(x=>x.addEventListener('click',()=>{const raw=state.subitems.find(v=>v.id===x.dataset.id);state.subEditor={id:raw.id,name:raw.name,code:raw.code||'',barcode:raw.barcode||'',price:Number(raw.price||0),optionTitle:raw.option_title||'Size',type:inferSubType(raw),images:raw.images||[],variants:(raw.variants||[]).map(v=>({id:v.id,color:v.color||'',size:v.size||'',stock:Number(v.stock||0),price:Number(v.price??raw.price??0),barcode:v.barcode||'',image:v.image_url||'',active:v.active!==false})),active:raw.active!==false};render();}));
    root.querySelector('[data-action="close-sub-editor"]')?.addEventListener('click',()=>{state.subEditor=null;render();});
    root.querySelector('#subitemEditor')?.addEventListener('submit',saveSubitem);
    root.querySelectorAll('[data-si]').forEach(x=>x.addEventListener('change',()=>{syncSubEditor();if(['type','optionTitle'].includes(x.dataset.si))render();}));
    root.querySelector('[data-action="add-sub-variant"]')?.addEventListener('click',()=>{syncSubEditor();state.subEditor.variants.push({color:'',size:'',stock:0,price:Number(state.subEditor.price||0),barcode:'',image:'',active:true});render();});
    root.querySelector('[data-action="quick-add-sub-variants"]')?.addEventListener('click',()=>{syncSubEditor();const values=String(root.querySelector('#subQuickValues')?.value||'').split(/[,\n|]+/).map(v=>v.trim()).filter(Boolean);if(!values.length){notify('Enter one or more subitem option values.');return;}const color=state.subEditor.type==='Colour + Option'?String(root.querySelector('#subQuickColor')?.value||'').trim():'';if(state.subEditor.type==='Colour + Option'&&!color){notify('Enter the colour for these options.');return;}const qty=Math.max(0,Number(root.querySelector('#subQuickQty')?.value||0)),price=Number(root.querySelector('#subQuickPrice')?.value||state.subEditor.price||0);values.forEach(size=>{const exists=state.subEditor.variants.some(v=>String(v.color||'').trim().toLowerCase()===color.toLowerCase()&&String(v.size||'').trim().toLowerCase()===size.toLowerCase());if(!exists)state.subEditor.variants.push({color,size,stock:qty,price,barcode:'',image:'',active:true});});render();});
    root.querySelectorAll('[data-remove-sub-variant]').forEach(x=>x.addEventListener('click',()=>{syncSubEditor();if(state.subEditor.variants.length>1)state.subEditor.variants.splice(Number(x.dataset.removeSubVariant),1);else state.subEditor.variants=[{color:'',size:'',stock:0,price:Number(state.subEditor.price||0),barcode:'',image:'',active:true}];render();}));
    root.querySelectorAll('[data-remove-sub-image]').forEach(x=>x.addEventListener('click',()=>{syncSubEditor();state.subEditor.images.splice(Number(x.dataset.removeSubImage),1);render();}));
    root.querySelector('#subImages')?.addEventListener('change',async e=>{syncSubEditor();try{const urls=await uploadMany([...e.target.files],'subitems');state.subEditor.images.push(...urls);render();}catch(err){notify(err.message||'Upload failed');}});
    root.querySelectorAll('[data-sub-variant-image-upload]').forEach(x=>x.addEventListener('change',async e=>{syncSubEditor();const i=Number(x.dataset.subVariantImageUpload),file=e.target.files?.[0];if(!file)return;try{const url=await B.uploadImage(file,'subitem-variants'),color=String(state.subEditor.variants[i]?.color||'').trim();if(state.subEditor.type==='Colour + Option'&&color)state.subEditor.variants.forEach(v=>{if(String(v.color||'').trim().toLowerCase()===color.toLowerCase())v.image=url;});else state.subEditor.variants[i].image=url;render();}catch(err){notify(err.message||'Subitem option image upload failed');}}));
    root.querySelectorAll('[data-clear-sub-variant-image]').forEach(x=>x.addEventListener('click',()=>{syncSubEditor();const i=Number(x.dataset.clearSubVariantImage),color=String(state.subEditor.variants[i]?.color||'').trim();if(state.subEditor.type==='Colour + Option'&&color)state.subEditor.variants.forEach(v=>{if(String(v.color||'').trim().toLowerCase()===color.toLowerCase())v.image='';});else if(state.subEditor.variants[i])state.subEditor.variants[i].image='';render();}));

    root.querySelector('#orderSearch')?.addEventListener('input',e=>{state.orderQuery=e.target.value;render();requestAnimationFrame(()=>root.querySelector('#orderSearch')?.focus());});
    root.querySelectorAll('[data-order-filter]').forEach(x=>x.addEventListener('click',()=>{state.orderFilter=x.dataset.orderFilter;render();}));
    root.querySelectorAll('[data-order-status]').forEach(x=>x.addEventListener('change',async()=>{const r=await sb().from('orders').update({status:x.value,updated_at:new Date().toISOString()}).eq('id',x.dataset.orderStatus);if(r.error)notify(r.error.message);else{await loadAll();notify('Order status updated.');}}));

    root.querySelector('#accountCreate')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await B.adminCreateAccount(Object.fromEntries(fd.entries()));state.profiles=await B.listProfiles();render();notify('Account created.');}catch(err){notify(err.message||'Could not create account');}});
    root.querySelector('[data-action="bootstrap-default-accounts"]')?.addEventListener('click',async()=>{if(!confirm('Create or reset the four default portal access accounts?'))return;try{await B.adminBootstrapAccounts();state.profiles=await B.listProfiles();render();notify('Default portal access is ready.');}catch(err){notify(err.message||'Could not create default access');}});
    root.querySelectorAll('[data-action="save-account"]').forEach(x=>x.addEventListener('click',async()=>{const id=x.dataset.id,role=root.querySelector('[data-account-role="'+id+'"]')?.value,active=root.querySelector('[data-account-active="'+id+'"]')?.checked,password=root.querySelector('[data-account-password="'+id+'"]')?.value||'';try{await B.adminUpdateAccount({id,role,active,...(password?{password}:{})});state.profiles=await B.listProfiles();render();notify('Account updated.');}catch(err){notify(err.message||'Could not update account');}}));
  }
  async function init(){
    if(!B?.configured?.()){state.loading=false;render();return;}
    try{state.profile=await B.staffProfile();}catch(_){}
    state.loading=false;if(state.profile&&roleOkay())await loadAll();else render();
  }
  init();
  setInterval(()=>{const live=(requested==='admin'&&['dashboard','orders','customers','carts','activity','stock','enquiries'].includes(state.view))||(requested==='receiver'&&state.view==='orders')||(requested==='staff'&&state.view==='stock');if(state.profile&&roleOkay()&&!state.loading&&!state.editor&&!state.b2bEditor&&!state.subEditor&&!state.categoryEditor&&!state.customCategoryEditor&&live)loadAll(true);},6000);
})();
